package com.interview.patterns.visitor;

public interface Expression {
    <R> R accept(ExpressionVisitor<R> visitor);
}

package com.interview.patterns.visitor;

public interface ExpressionVisitor<R> {
    R visitNumber(NumberExpression expr);
    R visitAdd(AddExpression expr);
    R visitMultiply(MultiplyExpression expr);
}

package com.interview.patterns.visitor;

public class NumberExpression implements Expression {
    private final double value;

    public NumberExpression(double value) {
        this.value = value;
    }

    public double getValue() {
        return value;
    }

    @Override
    public <R> R accept(ExpressionVisitor<R> visitor) {
        return visitor.visitNumber(this);
    }
}

package com.interview.patterns.visitor;

public class AddExpression implements Expression {
    private final Expression left;
    private final Expression right;

    public AddExpression(Expression left, Expression right) {
        this.left = left;
        this.right = right;
    }

    public Expression getLeft() {
        return left;
    }

    public Expression getRight() {
        return right;
    }

    @Override
    public <R> R accept(ExpressionVisitor<R> visitor) {
        return visitor.visitAdd(this);
    }
}

package com.interview.patterns.visitor;

public class MultiplyExpression implements Expression {
    private final Expression left;
    private final Expression right;

    public MultiplyExpression(Expression left, Expression right) {
        this.left = left;
        this.right = right;
    }

    public Expression getLeft() {
        return left;
    }

    public Expression getRight() {
        return right;
    }

    @Override
    public <R> R accept(ExpressionVisitor<R> visitor) {
        return visitor.visitMultiply(this);
    }
}

package com.interview.patterns.visitor;

public class ExpressionEvaluator implements ExpressionVisitor<Double> {
    public double evaluate(Expression expr) {
        return expr.accept(this);
    }

    @Override
    public Double visitNumber(NumberExpression expr) {
        return expr.getValue();
    }

    @Override
    public Double visitAdd(AddExpression expr) {
        return expr.getLeft().accept(this) + expr.getRight().accept(this);
    }

    @Override
    public Double visitMultiply(MultiplyExpression expr) {
        return expr.getLeft().accept(this) * expr.getRight().accept(this);
    }
}

package com.interview.patterns.visitor;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class ExpressionEvaluatorTest {
    @Test
    public void testSimpleEvaluation() {
        var evaluator = new ExpressionEvaluator();
        // (2 + 3) * 4 = 20
        var expr = new MultiplyExpression(
            new AddExpression(new NumberExpression(2.0), new NumberExpression(3.0)),
            new NumberExpression(4.0)
        );
        assertEquals(20.0, evaluator.evaluate(expr), 0.001);
    }
}

