public interface PaymentStrategy {
    PaymentProcessor.PaymentResult execute(PaymentProcessor.PaymentRequest request);
}

package com.interview.patterns.strategy;

public class CardPaymentStrategy implements PaymentStrategy {
    @Override
    public PaymentProcessor.PaymentResult execute(PaymentProcessor.PaymentRequest request) {
        return new PaymentProcessor.PaymentResult(true, request.amount() * 0.02);
    }
}

package com.interview.patterns.strategy;

public class CryptoPaymentStrategy implements PaymentStrategy {
    @Override
    public PaymentProcessor.PaymentResult execute(PaymentProcessor.PaymentRequest request) {
        return new PaymentProcessor.PaymentResult(true, 1.50);
    }
}

package com.interview.patterns.strategy;

public class CashPaymentStrategy implements PaymentStrategy {
    @Override
    public PaymentProcessor.PaymentResult execute(PaymentProcessor.PaymentRequest request) {
        return new PaymentProcessor.PaymentResult(true, 0.0);
    }
}

package com.interview.patterns.strategy;

import java.util.Map;
import java.util.HashMap;

public class PaymentProcessor {
    public enum PaymentType { CARD, CRYPTO, CASH }
    public record PaymentRequest(PaymentType type, double amount) {}
    public record PaymentResult(boolean success, double fee) {}

    private final Map<PaymentType, PaymentStrategy> strategies = new HashMap<>();

    public PaymentProcessor() {
        strategies.put(PaymentType.CARD, new CardPaymentStrategy());
        strategies.put(PaymentType.CRYPTO, new CryptoPaymentStrategy());
        strategies.put(PaymentType.CASH, new CashPaymentStrategy());
    }

    public PaymentResult processPayment(PaymentRequest request) {
        PaymentStrategy strategy = strategies.get(request.type());
        if (strategy == null) {
            throw new IllegalArgumentException("Unsupported type: " + request.type());
        }
        return strategy.execute(request);
    }
}

package com.interview.patterns.strategy;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class PaymentProcessorTest {
    @Test
    public void testCardPaymentFee() {
        var processor = new PaymentProcessor();
        var res = processor.processPayment(new PaymentProcessor.PaymentRequest(PaymentProcessor.PaymentType.CARD, 100.0));
        assertTrue(res.success());
        assertEquals(2.0, res.fee(), 0.001);
    }

    @Test
    public void testCryptoPaymentFee() {
        var processor = new PaymentProcessor();
        var res = processor.processPayment(new PaymentProcessor.PaymentRequest(PaymentProcessor.PaymentType.CRYPTO, 50.0));
        assertTrue(res.success());
        assertEquals(1.50, res.fee(), 0.001);
    }
}

