package com.interview.patterns.state;

public class OrderContext {
    public enum OrderStatus { PENDING, PAID, SHIPPED, CANCELLED }
    private OrderStatus status = OrderStatus.PENDING;

    public void pay() {
        switch (this.status) {
            case PENDING -> this.status = OrderStatus.PAID;
            case PAID -> throw new IllegalStateException("Order already paid");
            case SHIPPED -> throw new IllegalStateException("Cannot pay shipped order");
            case CANCELLED -> throw new IllegalStateException("Cannot pay cancelled order");
        }
    }

    public void ship() {
        switch (this.status) {
            case PENDING -> throw new IllegalStateException("Cannot ship unpaid order");
            case PAID -> this.status = OrderStatus.SHIPPED;
            case SHIPPED -> throw new IllegalStateException("Order already shipped");
            case CANCELLED -> throw new IllegalStateException("Cannot ship cancelled order");
        }
    }

    public void cancel() {
        switch (this.status) {
            case PENDING -> this.status = OrderStatus.CANCELLED;
            case PAID -> throw new IllegalStateException("Cannot cancel paid order directly");
            case SHIPPED -> throw new IllegalStateException("Cannot cancel shipped order");
            case CANCELLED -> throw new IllegalStateException("Order already cancelled");
        }
    }

    public String getStatus() {
        return this.status.name();
    }
}

package com.interview.patterns.state;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

